using System;using System.IO;using System.Windows;using System.Windows.Controls;using System.Windows.Documents;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using HdrPilot;
class ProgressCheck{
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Pump(int ms){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
 static int Count(Button b){var layer=AdornerLayer.GetAdornerLayer(b);var a=layer==null?null:layer.GetAdorners(b);return a==null?0:a.Length;}
 static void Save(FrameworkElement root,string path){root.UpdateLayout();var bitmap=new RenderTargetBitmap((int)root.ActualWidth,(int)root.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(root);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(path))png.Save(stream);}
 [STAThread] static void Main(string[] args){Core.Data=Path.Combine(args[0],"ui-test-data");Directory.CreateDirectory(Core.Data);var app=new Application();ButtonProgress.Start();var panel=new StackPanel{Margin=new Thickness(24)};var root=new AdornerDecorator{Child=panel};var window=new Window{Width=430,Height=245,Content=root,Background=new SolidColorBrush(Color.FromRgb(23,31,40)),ShowActivated=false,Left=-10000,Top=-10000};var button=new Button{Content="Installa RenoDX",Width=250,Height=40,HorizontalAlignment=HorizontalAlignment.Left};panel.Children.Add(button);var message=new TextBlock{Text="Pronto",Foreground=Brushes.White,Margin=new Thickness(0,24,0,0)};panel.Children.Add(message);string phase="Download";double pct=42;button.Click+=(s,e)=>{ButtonProgress.Report(phase,pct);};window.Show();Pump(100);
 button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump(100);Check(Count(button)==1,"progress missing");StatusFeedback.Error(message,"Il componente richiesto non è disponibile.");Pump(60);Check(((SolidColorBrush)message.Foreground).Color.R==255,"error not red");Save(root,Path.Combine(args[0],"progress-preview.png"));
 phase="Operazione completata";pct=100;button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));button.IsEnabled=false;Pump(150);Check(Count(button)==1,"terminal feedback missing");Pump(750);Check(Count(button)==0,"100 percent stuck on disabled button");Check((string)button.Content=="Installa RenoDX","button label changed");
 message.Text="File verificati";Pump(50);Check(((SolidColorBrush)message.Foreground).Color==Colors.White,"error color not reset: "+message.Foreground);message.Text="RenoDX NR: configurazione non compatibile.";Pump(50);Check(((SolidColorBrush)message.Foreground).Color.G==115,"unsupported not red");
 button.IsEnabled=true;phase="Download non riuscito";button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump(800);Check(Count(button)==0,"failed indicator stuck");
 phase="Verifica dei file";pct=-1;button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));button.IsEnabled=false;Pump(1300);Check(Count(button)==1,"active disabled operation lost its indicator");
 button.IsEnabled=true;button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump(80);panel.Children.Remove(button);Pump(80);panel.Children.Insert(0,button);Pump(80);Check(Count(button)==0,"orphan after unload");
 Check(!StatusFeedback.IsError("Nessun componente installato rilevato."),"normal empty state marked error");Check(!StatusFeedback.IsError("File installati; verifica l’attivazione in gioco."),"success marked error");
 window.Close();File.WriteAllText(Path.Combine(args[0],"ui-tests-passed.txt"),"PASS: active indicator, terminal on disabled button, error, idle cleanup, unload/reload cleanup, original label, red error/unsupported and reset to normal.");}
}

